import itertools

n = 4
total = sum(1 for _ in itertools.permutations(range(1, n + 1)))
best_wins = 0
for r in range(0, n):
    wins = 0
    for perm in itertools.permutations(range(1, n + 1)):
        chosen = None
        for k in range(r, n):
            if perm[k] == max(perm[:k + 1]):
                chosen = k
                break
        if chosen is not None and perm[chosen] == n:
            wins += 1
    best_wins = max(best_wins, wins)
print(best_wins, total)
